param([string]$RepositoryRoot)
$ErrorActionPreference='Stop'
. (Join-Path $RepositoryRoot 'WinAudioClean.ps1')
. (Join-Path $RepositoryRoot 'WinAudioClean.Settings.ps1')
. (Join-Path $RepositoryRoot 'WinAudioClean.Batch.ps1')
$root=Join-Path $RepositoryRoot ('.wac-local/WAC-M3-02/smoke-'+[guid]::NewGuid().ToString('N'))
$null=[IO.Directory]::CreateDirectory($root)
$app=Join-Path $root 'stub.ps1'
[IO.File]::WriteAllText($app, @'
param([string]$inputPath)
[IO.File]::AppendAllText($env:WAC_SMOKE_RECORD,$inputPath+"`n",[Text.UTF8Encoding]::new($false))
switch ([IO.Path]::GetFileName($inputPath)) {
  'failed.wav' { Write-Error 'Controlled item failure' -ErrorAction Continue; exit 2 }
  'warning.wav' { exit 7 }
  'cancelled.wav' { exit 130 }
  default { exit 0 }
}
'@,[Text.UTF8Encoding]::new($false))
$manifest=Join-Path $root 'inputs.json'
[IO.File]::WriteAllText($manifest,'{"schemaVersion":1,"inputs":["literal %TOKEN% ! [a].wav","second.wav","second.wav"]}',[Text.UTF8Encoding]::new($false))
$inputs=@(Read-WacInputList -Path $manifest)
if ($inputs.Count -ne 3 -or $inputs[0] -cne (Join-Path $root 'literal %TOKEN% ! [a].wav') -or $inputs[1] -cne $inputs[2]) { throw 'Manifest anchoring/order/repetition failed.' }
$checks=1
foreach ($case in @(
 @{ Name='continuation'; Inputs=@('first.wav','failed.wav','last.wav'); Exit=6; States=@('SUCCESS','FAILED','SUCCESS'); Calls=3 },
 @{ Name='cancellation'; Inputs=@('first.wav','cancelled.wav','last.wav'); Exit=130; States=@('SUCCESS','CANCELLED','NOT_STARTED'); Calls=2 },
 @{ Name='single-warning'; Inputs=@('warning.wav'); Exit=7; States=@('WARNING'); Calls=1 }
)) {
 $env:WAC_SMOKE_RECORD=Join-Path $root ($case.Name+'.calls.txt')
 $journal=Join-Path $root ($case.Name+'.jsonl')
 $settings=Resolve-WacSettings -Explicit @{ Mode='Raw'; OutputDirectory=$root }
 $result=Invoke-WacBatch -Inputs $case.Inputs -Parameters @{ NonInteractive=$true; BatchResultPath=$journal } -ResolvedSettings $settings -ApplicationPath $app
 $records=@([IO.File]::ReadAllLines($journal)|ForEach-Object { $_|ConvertFrom-Json })
 $states=@($records|Where-Object type -eq item|ForEach-Object status)
 if ($result.ExitCode -ne $case.Exit -or -not $result.ReportingComplete -or ($states -join ',') -cne ($case.States -join ',') -or [IO.File]::ReadAllLines($env:WAC_SMOKE_RECORD).Count -ne $case.Calls) { throw ($case.Name+' failed.') }
 if ($records[-1].exitCode -ne $case.Exit -or $records[-1].type -ne 'summary') { throw 'Summary mismatch.' }
 $checks++
}
$journal=Join-Path $root 'actual-main.jsonl'
& (Join-Path $RepositoryRoot 'WinAudioClean.ps1') -InputPaths @((Join-Path $root 'missing1.wav'),(Join-Path $root 'missing2.wav')) -Mode Raw -OutputDirectory $root -IgnoreSavedSettings -NonInteractive -BatchResultPath $journal
if ($LASTEXITCODE -ne 6) { throw 'Actual main list route failed.' }
$records=@([IO.File]::ReadAllLines($journal)|ForEach-Object { $_|ConvertFrom-Json })
if (@($records|Where-Object { $_.type -eq 'item' -and $_.exitCode -eq 2 }).Count -ne 2) { throw 'Actual preflight results missing.' }
$checks++
Write-Output ("Smoke passed: $checks checks; shell $($PSVersionTable.PSVersion).")
exit 0

run-smoke.py.source:
from pathlib import Path
import hashlib,json,os,shutil,subprocess,concurrent.futures,sys
root=Path.cwd(); scratch=root/'.wac-local/WAC-M3-02'
files=['WinAudioClean.ps1','WinAudioClean.Batch.ps1','WinAudioClean.Settings.ps1','WinAudioClean.IO.ps1']
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
source={f:sha(root/f) for f in files}
phase=sys.argv[1] if len(sys.argv)>1 else 'final'
shells={'ps51':str(Path(os.environ['SYSTEMROOT'])/'System32/WindowsPowerShell/v1.0/powershell.exe'),'ps7':shutil.which('pwsh.exe')}
assert all(shells.values())
env={k:v for k,v in os.environ.items() if k.upper()!='PSMODULEPATH'}
def run(item):
 name,exe=item
 command=[exe,'-NoLogo','-NoProfile','-ExecutionPolicy','Bypass','-File',str(scratch/'batch-smoke.ps1'),'-RepositoryRoot',str(root)]
 p=subprocess.run(command,cwd=root,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace',timeout=90)
 log=scratch/('batch-smoke-'+phase+'-'+name+'.txt');log.write_text(p.stdout,encoding='utf-8')
 return {'shell':name,'command':command,'exit_code':p.returncode,'log':log.name,'sha256':sha(log),'tail':p.stdout[-2000:]}
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:runs=list(pool.map(run,shells.items()))
after={f:sha(root/f) for f in files}
data={'source':source,'source_unchanged':source==after,'runs':runs}
(scratch/('batch-smoke-'+phase+'-results.json')).write_text(json.dumps(data,indent=2),encoding='utf-8')
for r in runs: print(json.dumps(r))
raise SystemExit(0 if source==after and all(r['exit_code']==0 for r in runs) else 1)
